package dev.appiaworks.protobuf.extras.serde;

import com.fasterxml.jackson.core.JsonGenerator;
import com.google.protobuf.Descriptors.Descriptor;
import com.google.protobuf.Message;
import dev.appiaworks.protobuf.extras.JsonWritable;
import dev.appiaworks.protobuf.extras.api.ApiStatus;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * Builds {@link TypedMessageWriter}s: one per generated message class, generated by the
 * {@link SerializerCodegen} this JVM offers and wired to the writers of the classes its fields
 * reach.
 *
 * <p>A class that writes its own JSON ({@link JsonWritable}, what {@code protoc-gen-java-extras}
 * generates) needs no generator: its writer is the method it carries, on any JVM. For every
 * other class ask {@link #available()} first: without a generator (a JVM below Java 25, or the
 * classfile module missing) no writer can be built, and compiled stubs are served by the other
 * tiers. The writers bake in the dialect in force when they are built, like the Tier 2
 * serializers do.
 */
@ApiStatus(ApiStatus.Status.INTERNAL)
public final class TypedWriters {

    private TypedWriters() {}

    /** Whether writers can be built on this JVM; a {@link JsonWritable} class needs none built. */
    public static boolean available() {
        return Codegen.available();
    }

    /**
     * The writer for the generated class of {@code prototype}, building it and every generated
     * class its fields reach that {@code cache} does not hold yet. New writers land in
     * {@code cache}, keyed by class, wired; a reachable class that cannot be served is left out
     * and its messages are written reflectively.
     *
     * @throws UnsupportedOperationException when the type reaches {@code google.protobuf.Any},
     *     whose JSON needs a type registry
     * @throws IllegalStateException when no generator is available ({@link #available()}) and the
     *     class does not write its own JSON
     * @throws Exception when the class itself cannot be served: an accessor is missing, or the
     *     generated class cannot be defined
     */
    public static TypedMessageWriter compile(Message prototype, Map<Class<? extends Message>, TypedMessageWriter> cache)
            throws Exception {
        Class<? extends Message> root = prototype.getClass();
        TypedMessageWriter known = cache.get(root);
        if (known != null) return known;
        Descriptor descriptor = prototype.getDescriptorForType();
        if (DynamicSerializerCompiler.containsAny(descriptor)) {
            throw new UnsupportedOperationException(
                    "message references google.protobuf.Any — requires TypeRegistry (Tier 3)");
        }
        if (ProtoWkt.isWkt(descriptor)) {
            TypedMessageWriter writer = wktWriter();
            cache.put(root, writer);
            return writer;
        }
        if (prototype instanceof JsonWritable) {
            // Generated at build time: the class writes itself and whatever it reaches.
            TypedMessageWriter writer = generatedWriter();
            cache.put(root, writer);
            return writer;
        }
        SerializerCodegen codegen = Codegen.provider();

        // Build the root and everything it reaches, then wire, then publish: a writer another
        // caller can see is never still being wired.
        Map<Class<? extends Message>, TypedMessageWriter> fresh = new LinkedHashMap<>();
        Map<Class<? extends Message>, TypedWriterPlan> plans = new LinkedHashMap<>();
        Set<Class<? extends Message>> failed = new HashSet<>();
        Deque<Message> pending = new ArrayDeque<>();
        pending.add(prototype);
        while (!pending.isEmpty()) {
            Message next = pending.poll();
            Class<? extends Message> type = next.getClass();
            if (cache.containsKey(type) || fresh.containsKey(type) || failed.contains(type)) continue;
            Descriptor d = next.getDescriptorForType();
            if (ProtoWkt.isWkt(d)) {
                fresh.put(type, wktWriter());
                continue;
            }
            TypedWriterPlan plan;
            TypedMessageWriter writer;
            try {
                plan = TypedWriterPlan.of(type, d);
                writer = codegen.typedWriter(plan);
            } catch (Exception | LinkageError e) {
                if (type == root) throw e;
                failed.add(type); // this nested type is written reflectively
                continue;
            }
            fresh.put(type, writer);
            plans.put(type, plan);
            for (Class<? extends Message> nested : plan.nestedTypes().values()) {
                if (!cache.containsKey(nested) && !fresh.containsKey(nested)) pending.add(defaultInstance(nested));
            }
        }
        for (Map.Entry<Class<? extends Message>, TypedWriterPlan> entry : plans.entrySet()) {
            TypedMessageWriter writer = fresh.get(entry.getKey());
            for (Map.Entry<String, Class<? extends Message>> nested :
                    entry.getValue().nestedTypes().entrySet()) {
                TypedMessageWriter wired = fresh.get(nested.getValue());
                if (wired == null) wired = cache.get(nested.getValue());
                if (wired != null) writer.setNested(nested.getKey(), wired);
            }
        }
        cache.putAll(fresh);
        return fresh.get(root);
    }

    private static Message defaultInstance(Class<? extends Message> type) throws Exception {
        return (Message) type.getMethod("getDefaultInstance").invoke(null);
    }

    /** A class that carries its writer, from {@code protoc-gen-java-extras}. */
    private static TypedMessageWriter generatedWriter() {
        return new TypedMessageWriter() {
            @Override
            public void write(Message message, JsonGenerator gen) throws IOException {
                ((JsonWritable) message).writeJson(gen);
            }
        };
    }

    /** A single-value type at the top level: its JSON is the value, as {@code JsonFormat} prints it. */
    private static TypedMessageWriter wktWriter() {
        return new TypedMessageWriter() {
            @Override
            public void write(Message message, JsonGenerator gen) throws IOException {
                ProtoWkt.writeJson(gen, message);
            }
        };
    }
}
